const MeasureFeature={id:"measure",name:"Measure",icon:"straighten",route:!1,fittingType:"recess",photoData:null,render(e={}){return e.appointmentId?this.renderMeasureForm(e.appointmentId,e.measurementId):'<div class="empty-state"><span class="material-symbols-rounded">straighten</span><div>Select a visit to measure</div></div>'},async renderMeasureForm(e,t){const a=this.getUnitLabel();let s=this.mmToDisplay(10);const n="inches"===CONFIG.measurementUnit?"0.125":"cm"===CONFIG.measurementUnit?"0.1":"1";let i=null;if(t){try{i=await DB.db.measurements.get(parseInt(t)||t)}catch(e){}i&&(this.fittingType=i.fittingType||"recess",this.photoData=i.photos&&i.photos[0]||null,i.tolerance&&(s=this.mmToDisplay(i.tolerance)))}else this.fittingType="recess",this.photoData=null;const r=e=>i&&e?this.mmToDisplay(e):"";return`<div class="fade-in">\n      <div class="top-header">\n        <button class="btn btn-ghost btn-sm" onclick="App.navigate('appointments',{id:${e}})"><span class="material-symbols-rounded">arrow_back</span></button>\n        <h1 style="flex:1;text-align:center;font-size:18px;">${i?"Edit Measurement":"Measure"}</h1>\n        <div style="width:40px;"></div>\n      </div>\n      <div style="padding:16px;">\n        <div class="form-group"><label>Window / Location</label><input type="text" class="input" id="meas-name" placeholder="e.g. Living Room Bay - Left" value="${i?Utils.escapeAttr(i.windowName||""):""}"></div>\n\n        <div class="form-group"><label>Fitting Type</label>\n          <div class="segmented">\n            <button class="segment ${"recess"===this.fittingType?"active":""}" onclick="MeasureFeature.setFittingType('recess')" id="fit-recess">Recess</button>\n            <button class="segment ${"exact"===this.fittingType?"active":""}" onclick="MeasureFeature.setFittingType('exact')" id="fit-exact">Exact</button>\n          </div>\n        </div>\n\n        <div class="card" style="margin-bottom:16px;">\n          <div style="font-weight:600;margin-bottom:12px;display:flex;align-items:center;gap:8px;"><span class="material-symbols-rounded">width</span>Width (${a})</div>\n          <div class="form-row">\n            <div class="form-group" style="margin-bottom:0;"><label>Top</label><input type="number" class="input" id="meas-w-top" placeholder="0" step="${n}" value="${r(i?.widthTop)}" onchange="MeasureFeature.calculate()"></div>\n            <div class="form-group" style="margin-bottom:0;"><label>Middle</label><input type="number" class="input" id="meas-w-mid" placeholder="0" step="${n}" value="${r(i?.widthMiddle)}" onchange="MeasureFeature.calculate()"></div>\n          </div>\n          <div class="form-group" style="margin-top:12px;margin-bottom:0;"><label>Bottom</label><input type="number" class="input" id="meas-w-bot" placeholder="0" step="${n}" value="${r(i?.widthBottom)}" onchange="MeasureFeature.calculate()"></div>\n          <div style="margin-top:12px;padding-top:12px;border-top:1px solid var(--border-light);display:flex;justify-content:space-between;align-items:center;">\n            <span style="font-size:13px;color:var(--text-secondary);">Least: <strong id="calc-w-least">--</strong></span>\n            <span style="font-size:13px;color:var(--primary);font-weight:600;">Use: <strong id="calc-w-use">--</strong></span>\n          </div>\n        </div>\n\n        <div class="card" style="margin-bottom:16px;">\n          <div style="font-weight:600;margin-bottom:12px;display:flex;align-items:center;gap:8px;"><span class="material-symbols-rounded">height</span>Drop (${a})</div>\n          <div class="form-row">\n            <div class="form-group" style="margin-bottom:0;"><label>Left</label><input type="number" class="input" id="meas-d-left" placeholder="0" step="${n}" value="${r(i?.dropLeft)}" onchange="MeasureFeature.calculate()"></div>\n            <div class="form-group" style="margin-bottom:0;"><label>Centre</label><input type="number" class="input" id="meas-d-centre" placeholder="0" step="${n}" value="${r(i?.dropCentre)}" onchange="MeasureFeature.calculate()"></div>\n          </div>\n          <div class="form-group" style="margin-top:12px;margin-bottom:0;"><label>Right</label><input type="number" class="input" id="meas-d-right" placeholder="0" step="${n}" value="${r(i?.dropRight)}" onchange="MeasureFeature.calculate()"></div>\n          <div style="margin-top:12px;padding-top:12px;border-top:1px solid var(--border-light);display:flex;justify-content:space-between;align-items:center;">\n            <span style="font-size:13px;color:var(--text-secondary);">Least: <strong id="calc-d-least">--</strong></span>\n            <span style="font-size:13px;color:var(--primary);font-weight:600;">Use: <strong id="calc-d-use">--</strong></span>\n          </div>\n        </div>\n\n        <div class="card" style="margin-bottom:16px;">\n          <div style="font-weight:600;margin-bottom:12px;display:flex;align-items:center;gap:8px;"><span class="material-symbols-rounded">square_foot</span>Diagonal Check</div>\n          <div class="form-row">\n            <div class="form-group" style="margin-bottom:0;"><label>TL → BR (${a})</label><input type="number" class="input" id="meas-diag-1" placeholder="0" step="${n}" value="${r(i?.diagonalTlBr)}" onchange="MeasureFeature.calculate()"></div>\n            <div class="form-group" style="margin-bottom:0;"><label>TR → BL (${a})</label><input type="number" class="input" id="meas-diag-2" placeholder="0" step="${n}" value="${r(i?.diagonalTrBl)}" onchange="MeasureFeature.calculate()"></div>\n          </div>\n          <div style="margin-top:12px;display:flex;align-items:center;gap:8px;">\n            <span id="diag-status-icon" class="material-symbols-rounded" style="color:var(--text-tertiary);">help</span>\n            <span id="diag-status" style="font-size:13px;color:var(--text-secondary);">Enter diagonals to check squareness</span>\n          </div>\n        </div>\n\n        <div class="form-group"><label>Tolerance (${a}) — for recess fitting</label><input type="number" class="input" id="meas-tolerance" value="${s}" step="${n}" onchange="MeasureFeature.calculate()"></div>\n        <div class="form-group"><label>Notes</label><textarea class="textarea" id="meas-notes" placeholder="e.g. Slight bow in sill, handle obstruction...">${i?Utils.escapeHtml(i.notes||""):""}</textarea></div>\n\n        <div class="form-group">\n          <label>Photo</label>\n          <button class="btn btn-outline btn-sm" onclick="document.getElementById('meas-photo').click()"><span class="material-symbols-rounded">photo_camera</span>Take Photo</button>\n          <input type="file" id="meas-photo" accept="image/*" capture="environment" style="display:none;" onchange="MeasureFeature.handlePhoto(event)">\n          <div id="meas-photo-preview" style="margin-top:8px;">${this.photoData?`<img src="${this.photoData}" style="max-width:100%;border-radius:8px;">`:""}</div>\n        </div>\n\n        <button class="btn btn-primary btn-block" style="margin-top:8px;" onclick="MeasureFeature.save(${e}, ${i?i.id:"null"})">${i?"Save Changes":"Save Measurement"}</button>\n        ${i?`\n          <button class="btn btn-danger btn-block" style="margin-top:8px;" onclick="MeasureFeature.deleteMeasurement(${i.id}, ${e})">\n            <span class="material-symbols-rounded">delete</span> Delete Measurement\n          </button>\n        `:""}\n      </div>\n    </div>`},setFittingType(e){this.fittingType=e,document.getElementById("fit-recess").classList.toggle("active","recess"===e),document.getElementById("fit-exact").classList.toggle("active","exact"===e),this.calculate()},getUnitLabel:()=>"inches"===CONFIG.measurementUnit?"in":"cm"===CONFIG.measurementUnit?"cm":"mm",displayToMm(e){const t=parseFloat(e)||0;return"inches"===CONFIG.measurementUnit?25.4*t:"cm"===CONFIG.measurementUnit?10*t:t},mmToDisplay:e=>"inches"===CONFIG.measurementUnit?Number((e/25.4).toFixed(3)):"cm"===CONFIG.measurementUnit?Number((e/10).toFixed(1)):e,readMeasurement(e){return this.displayToMm(document.getElementById(e)?.value)},formatMeasurement:e=>e>0?Utils.formatMeasurement(Math.round(10*e)/10):"--",calculate(){const e=this.readMeasurement("meas-w-top"),t=this.readMeasurement("meas-w-mid"),a=this.readMeasurement("meas-w-bot"),s=Math.min(e,t,a),n=this.readMeasurement("meas-tolerance")||10,i="recess"===this.fittingType?s-n:s;document.getElementById("calc-w-least").textContent=this.formatMeasurement(s),document.getElementById("calc-w-use").textContent=this.formatMeasurement(i);const r=this.readMeasurement("meas-d-left"),o=this.readMeasurement("meas-d-centre"),l=this.readMeasurement("meas-d-right"),d=Math.min(r,o,l),m=d;document.getElementById("calc-d-least").textContent=this.formatMeasurement(d),document.getElementById("calc-d-use").textContent=this.formatMeasurement(m);const c=this.readMeasurement("meas-diag-1"),p=this.readMeasurement("meas-diag-2");if(c>0&&p>0){const e=Math.abs(c-p),t=e<=5,a=document.getElementById("diag-status"),s=document.getElementById("diag-status-icon");t?(a.textContent=`Square (variance: ${Utils.formatMeasurement(e)})`,a.style.color="var(--secondary)",s.textContent="check_circle",s.style.color="var(--secondary)"):(a.textContent=`Not square (variance: ${Utils.formatMeasurement(e)})`,a.style.color="var(--warning)",s.textContent="warning",s.style.color="var(--warning)")}},async handlePhoto(e){const t=e.target.files[0];if(!t)return;const a=await Utils.fileToBase64(t);this.photoData=a,document.getElementById("meas-photo-preview").innerHTML=`<img src="${a}" style="max-width:100%;border-radius:8px;">`},async save(e,t){const a=document.getElementById("meas-name").value.trim();if(!a)return void Toast.show("Please enter a window name","error");const s={appointmentId:e,windowName:a,fittingType:this.fittingType,inputUnit:CONFIG.measurementUnit||"mm",widthTop:this.readMeasurement("meas-w-top"),widthMiddle:this.readMeasurement("meas-w-mid"),widthBottom:this.readMeasurement("meas-w-bot"),dropLeft:this.readMeasurement("meas-d-left"),dropCentre:this.readMeasurement("meas-d-centre"),dropRight:this.readMeasurement("meas-d-right"),diagonalTlBr:this.readMeasurement("meas-diag-1"),diagonalTrBl:this.readMeasurement("meas-diag-2"),tolerance:this.readMeasurement("meas-tolerance")||10,notes:document.getElementById("meas-notes")?.value||"",photos:this.photoData?[this.photoData]:[]};if(t){const e=Math.min(s.widthTop,s.widthMiddle,s.widthBottom),a=Math.min(s.dropLeft,s.dropCentre,s.dropRight),n=Math.abs(s.diagonalTlBr-s.diagonalTrBl);await DB.db.measurements.update(t,{...s,widthLeast:e,dropLeast:a,widthUsed:"recess"===s.fittingType?e-s.tolerance:e,dropUsed:a,diagonalVariance:n,isSquare:n<=5}),Toast.show("Measurement updated","success")}else await DB.addMeasurement(s),Toast.show("Measurement saved","success");App.navigate("appointments",{id:e})},async deleteMeasurement(e,t){const a=`\n      <div class="sheet-handle"></div>\n      <div class="sheet-header">\n        <h3>Delete Measurement</h3>\n        <button class="btn btn-ghost btn-sm" onclick="App.closeModal()">\n          <span class="material-symbols-rounded">close</span>\n        </button>\n      </div>\n      <div class="sheet-body">\n        <div style="font-size:14px;color:var(--text-secondary);line-height:1.5;margin-bottom:14px;">\n          This can't be undone.\n        </div>\n        <button class="btn btn-danger btn-block" onclick="MeasureFeature.confirmDeleteMeasurement(${e}, ${t})">\n          Delete Measurement\n        </button>\n      </div>\n    `;App.openModal(a)},async confirmDeleteMeasurement(e,t){try{await DB.db.measurements.delete(e),App.closeModal(),Toast.show("Measurement deleted","success"),App.navigate("appointments",{id:t})}catch(e){console.error("Delete measurement error:",e),Toast.show("Failed to delete measurement","error")}}};App.registerFeature(MeasureFeature);
